// Transmission state machine — a verbatim port of `crates/light-core/src/transmission.rs`.
//
// Why port instead of re-derive: the machine encodes the product's most
// important rule, "receiving light is not learning". The port is locked by
// `packages/protocol/fixtures/transmission_fsm.json` (220 cases generated by the
// Rust implementation), so the two cannot drift silently.

export const STATES = [
  "CREATED", "OFFERED", "RECEIVED", "ACCEPTED", "LEARNING",
  "ACTIVATED", "ACKNOWLEDGED", "CANCELLED", "EXPIRED", "REJECTED", "REVOKED",
];

export const EVENTS = [
  "OFFER", "OPEN", "ACCEPT", "CONFIRM", "REJECT",
  "EXPIRE", "CANCEL", "ACTIVATE", "ACKNOWLEDGE", "REVOKE",
];

const TERMINAL = new Set(["CANCELLED", "EXPIRED", "REJECTED", "REVOKED"]);
const CAN_EXPIRE = new Set(["CREATED", "OFFERED", "RECEIVED"]);
const REQUIRES_LIVE = new Set(["OFFER", "OPEN", "ACCEPT", "CONFIRM", "REJECT"]);
const REPLAY_ON_ACCEPT = new Set(["ACCEPTED", "LEARNING", "ACTIVATED", "ACKNOWLEDGED"]);
const REVOCABLE = new Set(["ACCEPTED", "LEARNING", "ACTIVATED", "ACKNOWLEDGED"]);

export function isTerminal(state) {
  return TERMINAL.has(state);
}

/**
 * Apply one event. Pure: no clock, no database.
 *
 * @param {{state:string, initiatorConfirmed:boolean, receiverConfirmed:boolean, version:number}} session
 * @param {string} event
 * @param {{nowMs:number, expiresAtMs:number, activationEvidenceOk:boolean}} ctx
 * @returns {{ok:true,state:string,effects:string[],replayed:boolean,version:number}|{ok:false,error:string}}
 */
export function applyEvent(session, event, ctx) {
  const state = session.state;
  const illegal = () => ({ ok: false, error: "IllegalTransition" });

  if (TERMINAL.has(state)) return illegal();

  if (REQUIRES_LIVE.has(event) && ctx.nowMs > ctx.expiresAtMs) {
    return { ok: false, error: "Expired" };
  }

  const succeed = (nextState, effects = [], replayed = false) => ({
    ok: true,
    state: nextState,
    effects,
    replayed,
    version: replayed ? session.version : session.version + 1,
  });

  const settle = () => {
    if (session.receiverConfirmed && session.initiatorConfirmed) {
      // ACCEPTED exists only inside this transition: the edge is formed, and the
      // session immediately enters LEARNING, waiting for real usage.
      return succeed("LEARNING", ["EdgeFormed", "TokenInvalidated"]);
    }
    return succeed("RECEIVED", []);
  };

  switch (event) {
    case "OFFER":
      if (state !== "CREATED") return illegal();
      return succeed("OFFERED");

    case "OPEN":
      if (state !== "OFFERED") return illegal();
      return succeed("RECEIVED");

    case "ACCEPT": {
      if (state !== "RECEIVED") {
        return REPLAY_ON_ACCEPT.has(state) ? succeed(state, [], true) : illegal();
      }
      session.receiverConfirmed = true;
      return settle();
    }

    case "CONFIRM": {
      if (state !== "RECEIVED") {
        return REPLAY_ON_ACCEPT.has(state) ? succeed(state, [], true) : illegal();
      }
      session.initiatorConfirmed = true;
      return settle();
    }

    case "REJECT":
      if (state !== "RECEIVED") return illegal();
      return succeed("REJECTED", ["TokenInvalidated"]);

    case "EXPIRE":
      if (!CAN_EXPIRE.has(state)) return illegal();
      return succeed("EXPIRED", ["TokenInvalidated"]);

    case "CANCEL":
      if (!(state === "CREATED" || state === "OFFERED")) return illegal();
      return succeed("CANCELLED", ["TokenInvalidated"]);

    case "ACTIVATE": {
      if (state === "ACTIVATED" || state === "ACKNOWLEDGED") {
        return succeed(state, [], true);
      }
      if (state !== "LEARNING") return illegal();
      if (!ctx.activationEvidenceOk) {
        return { ok: false, error: "ActivationEvidenceMissing" };
      }
      return succeed("ACTIVATED", ["EdgeActivated"]);
    }

    case "ACKNOWLEDGE": {
      if (state === "ACKNOWLEDGED") return succeed(state, [], true);
      if (state !== "ACTIVATED") return illegal();
      return succeed("ACKNOWLEDGED", ["EchoQueued"]);
    }

    case "REVOKE":
      if (!REVOCABLE.has(state)) return illegal();
      return succeed("REVOKED", ["EdgeRevoked"]);

    default:
      return illegal();
  }
}

/** Normalise a database row into the shape `applyEvent` expects. */
export function sessionFromRow(row) {
  return {
    state: row.state,
    initiatorConfirmed: Boolean(row.initiator_confirmed),
    receiverConfirmed: Boolean(row.receiver_confirmed),
    version: Number(row.version),
  };
}
